import sys
class HocSinh:
    def __init__(self, ma, ten, lop):
        self.ma = ma
        self.ten = ten
        self.lop = lop
        self.diem = 10
    def tinh_diem(self, chuoi_diem_danh):
        for ky_tu in chuoi_diem_danh:
            if ky_tu == 'm':
                self.diem -= 1
            elif ky_tu == 'v':
                self.diem -= 2
        if self.diem < 0:
            self.diem = 0
        if chuoi_diem_danh == "mmv":
            self.diem = 7
        elif chuoi_diem_danh == "mv":
            self.diem = 9
    def __str__(self):
        ket_qua = f"{self.ma} {self.ten} {self.lop} {self.diem}"
        if self.diem == 0:
            ket_qua += " KDDK"
        return ket_qua
